@php
function type($adress) {
if ($adress->commerce === 1) {
return "Commerce";
} else if ($adress->appartement === 1) {
return "Appartement";
} else if ($adress->maison === 1) {
return "Maison";
} else if ($adress->industrie === 1) {
return "Industrie";
} else {
return "Inconnu";
}
}
